<?php
require_once '_bootstrap.php';
require_once __DIR__.'/../booking-pricing.php';
require_admin_permission('bookings.manage');
$db=admin_db();
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;
$statement=$db->prepare('SELECT b.*,p.name package_name,p.description package_description,s.name state_name FROM bookings b LEFT JOIN packages p ON p.id=b.package_id LEFT JOIN states s ON s.id=p.state_id WHERE b.id=?');
if(!$statement)redirect_with_message('bookings.php','Booking details are temporarily unavailable.');
$statement->bind_param('i',$id);$statement->execute();$booking=$statement->get_result()->fetch_assoc();
if(!$booking)redirect_with_message('bookings.php','Booking not found.');
$travellers=[];$statement=$db->prepare('SELECT name,relationship,date_of_birth,gender,phone,age_category,medical_issues,is_pwd,pwd_details,meal_plan_name,food_preference,dietary_notes,meal_surcharge FROM booking_travellers WHERE booking_id=? ORDER BY id');$statement->bind_param('i',$id);$statement->execute();$result=$statement->get_result();while($row=$result->fetch_assoc())$travellers[]=$row;
$history=[];$statement=$db->prepare('SELECT old_status,new_status,note,changed_by,created_at FROM booking_status_history WHERE booking_id=? ORDER BY created_at DESC,id DESC');$statement->bind_param('i',$id);$statement->execute();$result=$statement->get_result();while($row=$result->fetch_assoc())$history[]=$row;
$payments=[];$statement=$db->prepare('SELECT amount,method,transaction_reference,status,created_at FROM payments WHERE booking_id=? ORDER BY id DESC');$statement->bind_param('i',$id);$statement->execute();$result=$statement->get_result();while($row=$result->fetch_assoc())$payments[]=$row;
$amendments=$db->execute_query('SELECT * FROM booking_amendments WHERE booking_id=? ORDER BY id DESC',[$id])->fetch_all(MYSQLI_ASSOC);
$cancellations=$db->execute_query('SELECT * FROM cancellation_requests WHERE booking_id=? ORDER BY id DESC',[$id])->fetch_all(MYSQLI_ASSOC);
$travellerCount=max(1,(int)$booking['people']);$hotelUpgrade=max(0,(float)($booking['hotel_surcharge_total']??0));$mealUpgrade=max(0,(float)($booking['meal_surcharge_total']??0));$packageSubtotal=max(0,(float)($booking['base_amount']??0)-$hotelUpgrade-$mealUpgrade);$unitPrice=(float)($booking['package_unit_price']??0);if($unitPrice<=0)$unitPrice=$packageSubtotal/$travellerCount;$priceRows=booking_price_rows_from_travellers($travellers,$unitPrice,$packageSubtotal,$travellerCount);$discount=max(0,(float)($booking['discount_amount']??0));$duration=max(1,(new DateTimeImmutable($booking['from_date']))->diff(new DateTimeImmutable($booking['to_date']))->days+1);
$foodCounts=['Vegetarian'=>0,'Non-vegetarian'=>0];foreach($travellers as $traveller){if(isset($foodCounts[$traveller['food_preference']]))$foodCounts[$traveller['food_preference']]++;}
$pageTitle='Booking Details';
include '_header.php';
?>
<div class="page-head"><div><span>Booking review</span><h1><?php echo e($booking['booking_reference']?:'#'.$booking['id']);?></h1><p><?php echo e($booking['customer_name']);?> · <?php echo e($booking['user_email']);?></p></div><a class="reset-btn" href="bookings.php"><i class="fa-solid fa-arrow-left"></i> Back to bookings</a></div>
<div class="booking-detail-grid">
<section class="panel booking-detail-panel"><div class="panel-head"><div><span>Dining requirements</span><h2><?php echo e($booking['meal_plan_name']??'Standard meals (included)');?></h2></div><span class="pill"><?php echo $mealUpgrade>0?inr($mealUpgrade).' upgrade':'Included';?></span></div><div class="booking-detail-facts"><span><b>Trip theme</b><?php echo e(ucwords(str_replace('_',' ',$booking['trip_theme']??'leisure')));?></span><span><b>Vegetarian</b><?php echo (int)$foodCounts['Vegetarian'];?> traveller(s)</span><span><b>Non-vegetarian</b><?php echo (int)$foodCounts['Non-vegetarian'];?> traveller(s)</span><span><b>Rate</b><?php echo $mealUpgrade>0?inr($booking['meal_surcharge_per_traveller']).' per traveller':'Included in package';?></span></div></section>
<section class="panel booking-detail-panel"><div class="panel-head"><h2>Trip details</h2><span class="pill"><?php echo e(ucwords(str_replace('_',' ',$booking['status'])));?></span></div><div class="booking-detail-facts"><span><b>Package</b><?php echo e($booking['package_name']?:$booking['destination']);?></span><span><b>Destination</b><?php echo e($booking['destination']);?><?php if($booking['state_name']):?><small><?php echo e($booking['state_name']);?></small><?php endif;?></span><span><b>Travel dates</b><?php echo e(date('d M Y',strtotime($booking['from_date'])));?> to <?php echo e(date('d M Y',strtotime($booking['to_date'])));?></span><span><b>Duration</b><?php echo $duration;?> days</span><span><b>Accommodation</b><?php echo e($booking['hotel']);?></span><span><b>Travellers</b><?php echo (int)$booking['people'];?></span><span><b>Category</b><?php echo e(ucwords($booking['trip_category']));?></span><span><b>Payment status</b><?php echo e(ucfirst($booking['payment_status']));?></span></div><?php if($booking['package_description']):?><div class="booking-detail-note"><b>Package details</b><p><?php echo nl2br(e($booking['package_description']));?></p></div><?php endif;?><?php if($booking['customer_note']):?><div class="booking-detail-note"><b>Customer request</b><p><?php echo nl2br(e($booking['customer_note']));?></p></div><?php endif;?><?php if($booking['admin_note']):?><div class="booking-customer-update"><b>Latest customer update sent</b><p><?php echo nl2br(e($booking['admin_note']));?></p></div><?php endif;?></section>
<section class="panel booking-detail-panel"><div class="panel-head"><h2>Travellers</h2><small><?php echo count($travellers);?> saved record(s)</small></div><?php if($travellers):?><div class="table-wrap"><table><thead><tr><th>Name</th><th>Relationship</th><th>Age group</th><th>Food preference</th><th>Assistance</th></tr></thead><tbody><?php foreach($travellers as $traveller):?><tr><td><strong><?php echo e($traveller['name']);?></strong><small><?php echo e($traveller['gender']);?><?php echo $traveller['phone']?' · '.e($traveller['phone']):'';?></small></td><td><?php echo e($traveller['relationship']);?></td><td><?php echo e(ucfirst($traveller['age_category']));?><?php if($traveller['date_of_birth']):?><small><?php echo e(date('d M Y',strtotime($traveller['date_of_birth'])));?></small><?php endif;?></td><td><strong><?php echo e($traveller['food_preference']);?></strong><small><?php echo e($traveller['meal_plan_name']);?></small><?php if($traveller['dietary_notes']):?><small><?php echo e($traveller['dietary_notes']);?></small><?php endif;?></td><td><?php if($traveller['is_pwd']):?><strong>PWD</strong><?php if($traveller['pwd_details']):?><small><?php echo e($traveller['pwd_details']);?></small><?php endif;?><?php echo $traveller['medical_issues']?'<small>'.e($traveller['medical_issues']).'</small>':'';?><?php else:?>None noted<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">No traveller records are attached to this booking.</p><?php endif;?></section>
<section class="panel booking-detail-panel"><div class="panel-head"><h2>Customer update history</h2></div><?php if($history):?><ol class="booking-history"><?php foreach($history as $change):?><li><div><strong><?php echo $change['old_status']?e(ucwords(str_replace('_',' ',$change['old_status'])).' to '):'';?><?php echo e(ucwords(str_replace('_',' ',$change['new_status'])));?></strong><small><?php echo e($change['changed_by']);?> · <?php echo e(date('d M Y, h:i A',strtotime($change['created_at'])));?></small></div><?php if($change['note']):?><p><?php echo nl2br(e($change['note']));?></p><?php endif;?></li><?php endforeach;?></ol><?php else:?><p class="muted">No status updates recorded yet.</p><?php endif;?></section>
<section class="panel booking-detail-panel"><div class="panel-head"><h2>Payment attempts</h2><span class="pill"><?php echo e(ucfirst($booking['payment_status']));?></span></div><?php if($payments):?><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Method</th><th>Result</th><th>Amount</th><th>Date</th></tr></thead><tbody><?php foreach($payments as $payment):?><tr><td><?php echo e(preg_replace('/^(?:DEMO|PRACTICE)-/','TI-PAY-',$payment['transaction_reference']));?></td><td><?php echo e(strtoupper(preg_replace('/^(demo_|practice_)/','',$payment['method'])));?></td><td><?php echo e(ucfirst($payment['status']));?></td><td><?php echo inr($payment['amount']);?></td><td><?php echo e(date('d M Y, h:i A',strtotime($payment['created_at'])));?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">No payment attempts recorded.</p><?php endif;?></section>
<?php if($amendments):?><section class="panel booking-detail-panel"><div class="panel-head"><h2>Date-change requests</h2></div><div class="request-review-list"><?php foreach($amendments as $request):?><article><span class="pill"><?php echo e(str_replace('_',' ',$request['status']));?></span><h3><?php echo e(date('d M Y',strtotime($request['old_from_date'])));?> - <?php echo e(date('d M Y',strtotime($request['old_to_date'])));?> <i class="fa-solid fa-arrow-right"></i> <?php echo e(date('d M Y',strtotime($request['requested_from_date'])));?> - <?php echo e(date('d M Y',strtotime($request['requested_to_date'])));?></h3><p><?php echo e($request['customer_reason']);?></p><?php if(in_array($request['status'],['requested','under_review'],true)):?><form method="post" action="booking-request-action.php" class="request-review-form"><?php echo csrf_input();?><input type="hidden" name="request_type" value="amendment"><input type="hidden" name="request_id" value="<?php echo (int)$request['id'];?>"><textarea name="admin_response" placeholder="Customer update or rejection reason"></textarea><button class="primary-btn" name="decision" value="approve"><i class="fa-solid fa-check"></i> Approve</button><button class="danger" name="decision" value="reject"><i class="fa-solid fa-xmark"></i> Reject</button></form><?php elseif($request['admin_response']):?><small><?php echo e($request['admin_response']);?></small><?php endif;?></article><?php endforeach;?></div></section><?php endif;?>
<?php if($cancellations):?><section class="panel booking-detail-panel"><div class="panel-head"><h2>Cancellation requests</h2></div><div class="request-review-list"><?php foreach($cancellations as $request):?><article><span class="pill"><?php echo e(str_replace('_',' ',$request['status']));?></span><h3><?php echo e($request['policy_name']);?></h3><p><?php echo e($request['reason']);?></p><div class="booking-detail-facts"><span><b>Paid</b><?php echo inr($request['paid_amount']);?></span><span><b>Estimated refund</b><?php echo inr($request['estimated_refund']);?></span><?php if($request['approved_refund']!==null):?><span><b>Approved refund</b><?php echo inr($request['approved_refund']);?></span><?php endif;?></div><?php if(in_array($request['status'],['requested','under_review'],true)):?><form method="post" action="booking-request-action.php" class="request-review-form"><?php echo csrf_input();?><input type="hidden" name="request_type" value="cancellation"><input type="hidden" name="request_id" value="<?php echo (int)$request['id'];?>"><label>Approved refund<input type="number" name="approved_refund" min="0" max="<?php echo e($request['paid_amount']);?>" step="0.01" value="<?php echo e($request['estimated_refund']);?>"></label><textarea name="admin_response" placeholder="Customer update or rejection reason"></textarea><button class="primary-btn" name="decision" value="approve"><i class="fa-solid fa-check"></i> Approve</button><button class="danger" name="decision" value="reject"><i class="fa-solid fa-xmark"></i> Reject</button></form><?php elseif($request['admin_response']):?><small><?php echo e($request['admin_response']);?></small><?php endif;?></article><?php endforeach;?></div></section><?php endif;?>
<?php if($booking['payment_status']==='paid'):?><section class="panel booking-detail-panel booking-admin-invoice"><div class="panel-head"><div><span>Invoice</span><h2>Paid booking invoice</h2></div><button class="primary-btn" type="button" onclick="window.print()"><i class="fa-solid fa-print"></i> Print / save invoice</button></div><div class="booking-detail-facts"><span><b>Customer</b><?php echo e($booking['customer_name']);?></span><span><b>Booking reference</b><?php echo e($booking['booking_reference']?:'#'.$booking['id']);?></span><?php foreach($priceRows as $row):?><span><b><?php echo e($row['label']);?></b><?php echo inr($row['unit']);?> × <?php echo (int)$row['count'];?> = <?php echo inr($row['total']);?></span><?php endforeach;?><?php if($hotelUpgrade>0):?><span><b>Accommodation upgrade</b><?php echo inr($booking['hotel_surcharge_per_traveller']);?> × <?php echo (int)$booking['people'];?> = <?php echo inr($hotelUpgrade);?></span><?php endif;?><?php if($discount>0):?><span><b>Offer discount</b>-<?php echo inr($discount);?></span><?php endif;?><span><b>Total paid</b><strong><?php echo inr($booking['total_amount']);?></strong></span><span><b>Payment status</b>Paid</span></div><?php if($payments):?><p><b>Payment reference:</b> <?php echo e($payments[0]['transaction_reference']);?> · <?php echo e(strtoupper(str_replace('demo_','',$payments[0]['method'])));?></p><?php endif;?></section><?php endif;?>
</div>
<?php include '_footer.php';?>
